class AIServiceRegistry {
    private val services = mutableMapOf<String, AIService>()

    fun registerAiService(service: AIService) {
        services[service.config.id] = service
    }

    fun getAvailableServices(capabilityCheck: (AIServiceCapability) -> Boolean): List<AIService> {
        return services.values.filter { service ->
            service.isAvailable && capabilityCheck(service.config.capabilities)
        }
    }

    fun getService(modelId: String): AIService? {
        return services[modelId]
    }

    fun getAllServices(): List<AIService> {
        return services.values.toList()
    }

    fun unregisterService(modelId: String) {
        services.remove(modelId)
    }
}

class AIServiceRouter(private val serviceRegistry: AIServiceRegistry) {

    suspend fun <T> routeByCapability(
        capabilityCheck: (AIServiceCapability) -> Boolean,
        operation: suspend (AIService) -> T
    ): T {
        val allServices = serviceRegistry.getAllServices()

        val availableServices = allServices.filter { service ->
            capabilityCheck(service.config.capabilities)
        }

        if (availableServices.isEmpty()) {
            throw AIServiceException("没有可用的AI服务支持该功能")
        }

        // 按成本排序选择服务
        val servicesByCost = availableServices.sortedBy { it.config.pricePerMillion }
        return tryRoute(servicesByCost, operation)
    }

    private suspend fun <T> tryRoute(
        services: List<AIService>,
        operation: suspend (AIService) -> T
    ): T {
        val exceptions = mutableListOf<Exception>()

        for (service in services) {
            try {
                val status = service.checkStatus()
                when (status) {
                    ServiceStatus.AVAILABLE -> return operation(service)
                    ServiceStatus.INSUFFICIENT_BALANCE -> 
                        exceptions.add(InsufficientBalanceException("${service.config.displayName} 余额不足"))
                    ServiceStatus.RATE_LIMITED -> 
                        exceptions.add(RateLimitException("${service.config.displayName} 频率限制"))
                    else -> exceptions.add(Exception("${service.config.displayName} 不可用"))
                }
            } catch (e: Exception) {
                exceptions.add(e)
            }
        }

        throw AIServiceException("所有可用服务都失败：${exceptions.joinToString { it.message ?: "未知错误" }}")
    }

    // 路由函数
    suspend fun routeBasicChat(operation: suspend (AIService) -> String): String {
        return routeByCapability(
            capabilityCheck = { it.supportBasicChat },
            operation = operation
        )
    }

    suspend fun routeMindMapGeneration(operation: suspend (AIService) -> MindMapEntity?): MindMapEntity? {
        return routeByCapability(
            capabilityCheck = { it.supportMindMapGeneration },
            operation = operation
        )
    }

    suspend fun routeDocumentParsing(operation: suspend (AIService) -> DocumentAnalysis): DocumentAnalysis {
        return routeByCapability(
            capabilityCheck = { it.supportDocumentParsing },
            operation = operation
        )
    }
}

object AIServiceConfigHelper {

    fun setupAIServiceConfigUI(
        secretIdField: View,
        apiKeyField: View,
        baseUrlField: View,
        regionField: View,
        modelField: View,
        config: AIServiceConfig
    ) {
        // 根据AIServiceRequiredFields显示/隐藏字段
        secretIdField.visibility = if (config.requiredFields.requireSecretId) View.VISIBLE else View.GONE
        apiKeyField.visibility = if (config.requiredFields.requireApiKey) View.VISIBLE else View.GONE
        baseUrlField.visibility = if (config.requiredFields.requireBaseUrl) View.VISIBLE else View.GONE
        regionField.visibility = if (config.requiredFields.requireRegion) View.VISIBLE else View.GONE
        modelField.visibility = if (config.requiredFields.requireModel) View.VISIBLE else View.GONE
    }

    fun getConfigData(
        secretId: String,
        apiKey: String,
        baseUrl: String,
        region: String,
        model: String,
        baseConfig: AIServiceConfig
    ): AIServiceConfig {
        return when (baseConfig) {
            is AIServiceConfig.TencentHunyuanConfig -> baseConfig.copy(
                secretId = secretId,
                apiKey = apiKey,
                baseUrl = baseUrl,
                region = region,
                model = model
            )
            is AIServiceConfig.BaichuanConfig -> baseConfig.copy(
                apiKey = apiKey,
                baseUrl = baseUrl,
                model = model
            )
        }
    }
}

class AIServiceDetailFragment : Fragment() {
    private var _binding: FragmentAiServiceDetailBinding? = null
    private val binding get() = _binding!!
    private lateinit var currentConfig: AIServiceConfig

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        val configType = arguments?.getString("config_type") ?: "tencent-hunyuan"
        currentConfig = when (configType) {
            "tencent-hunyuan" -> AIServiceConfig.TencentHunyuanConfig()
            "baichuan" -> AIServiceConfig.BaichuanConfig()
            else -> AIServiceConfig.TencentHunyuanConfig()
        }

        setupUI()
        setupSaveButton()
    }

    private fun setupUI() {
        binding.serviceTitle.text = "${currentConfig.displayName} 配置"

        AIServiceConfigHelper.setupAIServiceConfigUI(
            secretIdField = binding.secretIdField,
            apiKeyField = binding.apiKeyField,
            baseUrlField = binding.baseUrlField,
            regionField = binding.regionField,
            modelField = binding.modelField,
            config = currentConfig
        )
    }

    private fun setupSaveButton() {
        binding.saveButton.setOnClickListener {
            saveConfig()
        }
    }

    private fun saveConfig() {
        val updatedConfig = AIServiceConfigHelper.getConfigData(
            secretId = binding.secretIdInput.text.toString(),
            apiKey = binding.apiKeyInput.text.toString(),
            baseUrl = binding.baseUrlInput.text.toString(),
            region = binding.regionInput.text.toString(),
            model = binding.modelInput.text.toString(),
            baseConfig = currentConfig
        )

        // 保存到数据库
        saveToDatabase(updatedConfig)
        Toast.makeText(requireContext(), "配置保存成功", Toast.LENGTH_SHORT).show()
    }
}

class AIServiceDeepSeek(
    override val config: AIServiceConfig = AIServiceConfig.DeepSeekConfig(
        apiKey = "", // 需要用户配置
        baseUrl = "https://api.deepseek.com"
    )
) : AIService {

    private val client = OkHttpClient.Builder()
        .connectTimeout(30, TimeUnit.SECONDS)
        .readTimeout(30, TimeUnit.SECONDS)
        .build()

    override var isAvailable: Boolean = true
    override var remainingQuota: Long = config.freeQuota

    override suspend fun sendMessage(
        messages: List<MessageEntity>, 
        context: String
    ): AIServiceResponse {
        val startTime = System.currentTimeMillis()

        val requestBody = createChatRequestBody(messages, context)
        val request = Request.Builder()
            .url("${config.baseUrl}/v1/chat/completions")
            .post(requestBody)
            .addHeader("Authorization", "Bearer ${config.apiKey}")
            .addHeader("Content-Type", "application/json")
            .build()

        val response = client.newCall(request).execute()
        val content = parseChatResponse(response)

        val processingTime = System.currentTimeMillis() - startTime
        remainingQuota--

        return AIServiceResponse(
            content = content,
            processInfo = AIProcessInfo(
                serviceId = config.id,
                serviceName = config.displayName,
                modelUsed = config.model,
                processingTime = processingTime
            )
        )
    }

    override suspend fun processFileContent(
        content: String, 
        context: String
    ): AIServiceResponse {
        val prompt = "分析以下文件内容：\n\n$content\n\n上下文：$context"
        return sendMessage(
            listOf(MessageEntity(
                content = prompt,
                senderType = "USER",
                messageType = "TEXT"
            )),
            context
        )
    }

    override suspend fun generateMindMap(
        topicId: String, 
        learningGoal: String
    ): MindMapEntity? {
        // DeepSeek不支持思维导图，返回null
        return null
    }

    override suspend fun analyzeLearningProgress(
        conversationHistory: List<MessageEntity>
    ): ProgressAnalysis {
        val prompt = "分析以下对话历史，评估学习进度：\n\n${conversationHistory.joinToString("\n") { "${it.senderType}: ${it.content}" }}"

        val response = sendMessage(
            listOf(MessageEntity(
                content = prompt,
                senderType = "USER",
                messageType = "TEXT"
            )),
            ""
        )

        return parseProgressAnalysis(response.content)
    }

    override suspend fun generateSocraticQuestions(
        topic: String, 
        currentLevel: Int
    ): List<String> {
        val prompt = "为主题 '$topic' 生成3-5个苏格拉底式问题，当前水平：$currentLevel"

        val response = sendMessage(
            listOf(MessageEntity(
                content = prompt,
                senderType = "USER",
                messageType = "TEXT"
            )),
            ""
        )

        return response.content.lines().filter { it.isNotBlank() }
    }

    override suspend fun evaluateAnswer(
        userAnswer: String, 
        correctAnswer: String
    ): AnswerEvaluation {
        val prompt = "评估以下答案：\n用户答案：$userAnswer\n正确答案：$correctAnswer"

        val response = sendMessage(
            listOf(MessageEntity(
                content = prompt,
                senderType = "USER",
                messageType = "TEXT"
            )),
            ""
        )

        return parseAnswerEvaluation(response.content)
    }

    // 其他方法实现...
    override suspend fun checkStatus(): ServiceStatus {
        return try {
            val testRequest = Request.Builder()
                .url("${config.baseUrl}/v1/models")
                .get()
                .addHeader("Authorization", "Bearer ${config.apiKey}")
                .build()
            client.newCall(testRequest).execute()
            ServiceStatus.AVAILABLE
        } catch (e: Exception) {
            when (e) {
                is IOException -> ServiceStatus.UNAVAILABLE
                else -> ServiceStatus.UNAUTHORIZED
            }
        }
    }
}

