class AIServiceTencentHunyuan(
    override val config: AIServiceConfig = AIServiceConfig.TencentHunyuanConfig(
        secretId = "",
        apiKey = "",
        region = "ap-guangzhou",
        model = "hunyuan-lite"
    )
) : AIService {

    private val client = TencentCloudClient(
        secretId = config.secretId,
        secretKey = config.apiKey,
        region = config.region
    )

    override var isAvailable: Boolean = true
    override var remainingQuota: Long = config.freeQuota

    override suspend fun sendMessage(
        messages: List<MessageEntity>, 
        context: String
    ): AIServiceResponse {
        val startTime = System.currentTimeMillis()

        val request = ChatCompletionsRequest().apply {
            this.messages = messages.map { msg ->
                ChatMessage().apply {
                    role = if (msg.senderType == "USER") "user" else "assistant"
                    content = msg.content
                }
            }
            this.model = config.model
            this.stream = false
        }

        val response = client.chatCompletions(request)
        val content = response.choices.first().message.content

        val processingTime = System.currentTimeMillis() - startTime
        remainingQuota--

        return AIServiceResponse(
            content = content,
            processInfo = AIProcessInfo(
                serviceId = config.id,
                serviceName = config.displayName,
                modelUsed = config.model,
                processingTime = processingTime
            )
        )
    }

    override suspend fun generateMindMap(
        topicId: String, 
        learningGoal: String
    ): MindMapEntity? {
        val startTime = System.currentTimeMillis()

        val prompt = """
            基于学习主题：$topicId，学习目标：$learningGoal
            请生成一个结构化的思维导图，包含核心概念、知识点关联和学习路径
            输出格式要求：JSON格式的思维导图数据结构
        """.trimIndent()

        val response = sendMessage(
            listOf(MessageEntity(
                content = prompt,
                senderType = "USER",
                messageType = "TEXT"
            )),
            "mindmap"
        )

        val mindMap = parseMindMapFromResponse(response.content, topicId, learningGoal)
        val processingTime = System.currentTimeMillis() - startTime

        return mindMap?.copy(
            aiProcessInfo = AIProcessInfo(
                serviceId = config.id,
                serviceName = config.displayName,
                modelUsed = config.model,
                processingTime = processingTime
            )
        )
    }

    override suspend fun parseDocument(
        fileContent: String, 
        fileType: String
    ): DocumentAnalysis {
        val startTime = System.currentTimeMillis()

        val request = ReconstructDocumentRequest().apply {
            this.content = fileContent
            this.type = fileType
        }

        val response = client.reconstructDocument(request)

        return DocumentAnalysis(
            title = response.title ?: "",
            summary = response.summary ?: "",
            keyPoints = response.keyPoints ?: emptyList(),
            concepts = response.concepts?.map { 
                Concept(it.name, it.description) 
            } ?: emptyList()
        )
    }

    // 其他教育专用功能实现
    override suspend fun analyzeLearningProgress(
        conversationHistory: List<MessageEntity>
    ): ProgressAnalysis {
        val prompt = """
            分析以下对话历史，评估学习进度：
            ${conversationHistory.joinToString("\n") { "${it.senderType}: ${it.content}" }}

            请提供：
            1. 整体进度（百分比）
            2. 概念掌握度
            3. 知识缺口
            4. 推荐下一步
        """.trimIndent()

        val response = sendMessage(
            listOf(MessageEntity(
                content = prompt,
                senderType = "USER",
                messageType = "TEXT"
            )),
            "learning-analysis"
        )

        return parseProgressAnalysis(response.content)
    }

    override suspend fun generateSocraticQuestions(
        topic: String, 
        currentLevel: Int
    ): List<String> {
        val prompt = """
            为主题 '$topic' 生成3-5个苏格拉底式问题
            当前水平：$currentLevel/100

            问题设计原则：
            1. 从基础到深入递进
            2. 鼓励批判性思考
            3. 引导而非直接给出答案
        """.trimIndent()

        val response = sendMessage(
            listOf(MessageEntity(
                content = prompt,
                senderType = "USER",
                messageType = "TEXT"
            )),
            "socratic-questioning"
        )

        return response.content.lines().filter { it.isNotBlank() }
    }

    override suspend fun evaluateAnswer(
        userAnswer: String, 
        correctAnswer: String
    ): AnswerEvaluation {
        val prompt = """
            评估以下答案：
            用户答案：$userAnswer
            正确答案：$correctAnswer

            请提供：
            1. 正确性评分（0-100）
            2. 详细的反馈说明
            3. 改进建议
        """.trimIndent()

        val response = sendMessage(
            listOf(MessageEntity(
                content = prompt,
                senderType = "USER",
                messageType = "TEXT"
            )),
            "answer-evaluation"
        )

        return parseAnswerEvaluation(response.content)
    }

    // ... 其他接口方法
}

