class AIServiceInitializer {

    fun initializeServices(registry: AIServiceRegistry) {
        // 注册腾讯云混元AI服务（教育功能最强）
        val tencentService = AIServiceTencentHunyuan()
        registry.registerAiService(tencentService)

        // 注册DeepSeek AI服务（成本低，基础功能）
        val deepseekService = AIServiceDeepSeek()
        registry.registerAiService(deepseekService)

        // 注册MiniMax AI服务（创意写作）
        val minimaxService = AIServiceMiniMax()
        registry.registerAiService(minimaxService)

        // 注册百川AI服务（简单配置）
        val baichuanService = AIServiceBaichuan()
        registry.registerAiService(baichuanService)

        // 可以继续添加更多AI服务
        Log.i("AIServiceInitializer", "已注册 ${registry.getAllServices().size} 个AI服务")
    }
}

